def find_files(dir_path, extensions=['.jsonl', '.json'], max_depth=5):
    results = []
    visited = set()

    for root, dirs, files in os.walk(dir_path):
        # Limit depth by counting path segments
        rel_root = os.path.relpath(root, dir_path)
        if rel_root == '.':
